#include <stdlib.h>
#include <string.h>
#include <strings.h>
#include <unistd.h>
#include <errno.h>
#include <locale.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <ncurses.h>

// Globals for options
int opt_async = 0;
int opt_bold_mode = 0; // 0=default none, 1=random, 2=all, 3=heads only (flag -n)
int opt_force = 0;
int opt_linux = 0;
int opt_lock = 0;
int opt_old = 0;
int opt_screensaver = 0;
int opt_xwindow = 0;
int opt_rainbow = 0;
int opt_lambda = 0;
int opt_change = 0;
int opt_japanese = 0;
int update_delay = 4;
int matrix_color = COLOR_GREEN; // default green
char *opt_message = NULL;
int has_message = 0;
char *opt_tty = NULL;

void print_usage() {
    printf(" Usage: cmatrix -[abBcfhlsmVxk] [-u delay] [-C color] [-t tty] [-M message]\n");
    printf(" -a: Asynchronous scroll\n");
    printf(" -b: Bold characters on\n");
    printf(" -B: All bold characters (overrides -b)\n");
    printf(" -c: Use Japanese characters as seen in the original matrix. Requires appropriate fonts\n");
    printf(" -f: Force the linux $TERM type to be on\n");
    printf(" -l: Linux mode (uses matrix console font)\n");
    printf(" -L: Lock mode (can be closed from another terminal)\n");
    printf(" -o: Use old-style scrolling\n");
    printf(" -h: Print usage and exit\n");
    printf(" -n: No bold characters (overrides -b and -B, default)\n");
    printf(" -s: \"Screensaver\" mode, exits on first keystroke\n");
    printf(" -x: X window mode, use if your xterm is using mtx.pcf\n");
    printf(" -V: Print version information and exit\n");
    printf(" -M [message]: Prints your message in the center of the screen. Overrides -L's default message.\n");
    printf(" -u delay (0 - 10, default 4): Screen update delay\n");
    printf(" -C [color]: Use this color for matrix (default green)\n");
    printf(" -r: rainbow mode\n");
    printf(" -m: lambda mode\n");
    printf(" -k: Characters change while scrolling. (Works without -o opt.)\n");
    printf(" -t [tty]: Set tty to use\n");
}

void print_version() {
    printf(" CMatrix version 2.0 (compiled 22:13:51, Jun 11 2026)\n");
    printf("Email: abishekvashok@gmail.com\n");
    printf("Web: https://github.com/abishekvashok/cmatrix\n");
}

void print_invalid_color() {
    fprintf(stderr, " Invalid color selection\n");
    fprintf(stderr, " Valid colors are green, red, blue, white, yellow, cyan, magenta and black.\n");
}

int parse_color(const char *s, int *out) {
    if (strcasecmp(s, "green") == 0) { *out = COLOR_GREEN; return 1; }
    if (strcasecmp(s, "red") == 0) { *out = COLOR_RED; return 1; }
    if (strcasecmp(s, "blue") == 0) { *out = COLOR_BLUE; return 1; }
    if (strcasecmp(s, "white") == 0) { *out = COLOR_WHITE; return 1; }
    if (strcasecmp(s, "yellow") == 0) { *out = COLOR_YELLOW; return 1; }
    if (strcasecmp(s, "cyan") == 0) { *out = COLOR_CYAN; return 1; }
    if (strcasecmp(s, "magenta") == 0) { *out = COLOR_MAGENTA; return 1; }
    if (strcasecmp(s, "black") == 0) { *out = COLOR_BLACK; return 1; }
    return 0;
}

// Signal handlers
void handle_sigint(int sig) {
    (void)sig;
    endwin();
    exit(0);
}
void handle_sigterm(int sig) {
    (void)sig;
    endwin();
    exit(1);
}

int main(int argc, char *argv[]) {
    int opt;
    opterr = 0;
    // optstring: all flags, with : for those needing arg
    // a,b,B,c,f,l,L,o,h,n,s,x,V,r,m,k + u:,C:,M:,t:
    while ((opt = getopt(argc, argv, "abBcfhlLnosxVrmkM:u:C:t:h?")) != -1) {
        switch (opt) {
            case 'a':
                opt_async = !opt_async ? 1 : opt_async; // just set 1? Actually toggle? No, flag sets on. But what about -a -a? Should still be on. We'll set 1.
                // For interactive 'a' toggles, but flag just enables.
                opt_async = 1;
                break;
            case 'b':
                // -b sets random unless already all? To match -B -b => all
                if (opt_bold_mode != 2) opt_bold_mode = 1;
                break;
            case 'B':
                opt_bold_mode = 2;
                break;
            case 'c':
                opt_japanese = 1;
                break;
            case 'f':
                opt_force = 1;
                break;
            case 'l':
                opt_linux = 1;
                break;
            case 'L':
                opt_lock = 1;
                break;
            case 'o':
                opt_old = 1;
                break;
            case 'h':
            case '?':
                print_usage();
                return 0;
            case 'n':
                opt_bold_mode = 3; // heads only
                break;
            case 's':
                opt_screensaver = 1;
                break;
            case 'x':
                opt_xwindow = 1;
                break;
            case 'V':
                print_version();
                return 0;
            case 'r':
                opt_rainbow = 1;
                break;
            case 'm':
                opt_lambda = 1;
                break;
            case 'k':
                opt_change = 1;
                break;
            case 'M':
                opt_message = optarg;
                has_message = 1;
                break;
            case 'u':
                update_delay = atoi(optarg);
                break;
            case 'C': {
                int c;
                if (!parse_color(optarg, &c)) {
                    print_invalid_color();
                    return 0;
                }
                matrix_color = c;
                break;
            }
            case 't':
                opt_tty = optarg;
                break;
            default:
                print_usage();
                return 0;
        }
    }
    // Handle -f segfault / force linux BEFORE -t open
    if (opt_force) {
        // Deliberate segfault if TERM is NULL to match original
        char *t = getenv("TERM");
        // This will segfault if t is NULL
        if (strcmp(t, "linux") != 0) {
            setenv("TERM", "linux", 1);
        }
    }
    // Handle -t open
    FILE *tty_file = NULL;
