// Matrix structures
typedef struct {
    int y;       // head y position
    int len;     // trail length
    int space;   // gap after trail
    int speed;   // for async: update every speed frames
    int count;   // frame counter
    int active;  // always 1? Or waiting?
} MatrixCol;

MatrixCol *mcols = NULL;
