// Random char helpers
int rand_default_char() {
    // 33-122 inclusive (90 chars)
    return 33 + (rand() % 90);
}
int rand_old_char() {
    // 33-122 plus '|' (124) => 91 chars
    int r = rand() % 91;
    if (r == 90) return '|';
    return 33 + r;
}

// For -c gaps: same as default? Use 33-122
int rand_gap_char() {
    return 33 + (rand() % 90);
}

// UTF-8 helpers: encode wchar to utf8 string (caller provides buf[5])
int encode_utf8(int wc, char *buf) {
    if (wc < 0x80) {
        buf[0] = wc;
        buf[1] = '\0';
        return 1;
    } else if (wc < 0x800) {
        buf[0] = 0xC0 | (wc >> 6);
        buf[1] = 0x80 | (wc & 0x3F);
        buf[2] = '\0';
        return 2;
    } else {
        buf[0] = 0xE0 | (wc >> 12);
        buf[1] = 0x80 | ((wc >> 6) & 0x3F);
        buf[2] = 0x80 | (wc & 0x3F);
        buf[3] = '\0';
        return 3;
    }
}

int rand_katakana_wc() {
    // U+FF66 - U+FF9C (55 chars)
    return 0xFF66 + (rand() % 55);
}

// -x charset: U+00A6..U+00D8 plus extras
int x_extra_wcs[] = {0x2190, 0x2191, 0x2192, 0x2193, 0x2517, 0x255D, 0x25AE};
int rand_x_wc() {
    // 51 + 7 = 58 total
    int r = rand() % 58;
    if (r < 51) {
        return 0x00A6 + r; // A6-D8? 0xA6+50=0xD8, yes
    } else {
        return x_extra_wcs[r - 51];
    }
}

