// Message handling
char *active_message = NULL;
int active_msg_len = 0;
int msg_row = 0;
int msg_col = 0;
int msg_top = 0, msg_bottom = 0, msg_left = 0, msg_right = 0;

void compute_message_geometry() {
    active_message = NULL;
    active_msg_len = 0;
    if (has_message) {
        // -M given (even if empty? if empty, no message)
        if (opt_message && opt_message[0] != '\0') {
            active_message = opt_message;
            active_msg_len = strlen(opt_message);
        } else {
            active_message = NULL;
            active_msg_len = 0;
            return;
        }
    } else if (opt_lock) {
        active_message = "Computer locked.";
        active_msg_len = strlen(active_message);
    } else {
        return;
    }
    msg_row = LINES / 2;
    msg_col = (COLS - active_msg_len) / 2;
    if (msg_col < 0) msg_col = 0;
    // Blank rectangle: 3 rows high, width msg_len + 6 (3 padding each side)
    msg_top = msg_row - 1;
    msg_bottom = msg_row + 1;
    msg_left = msg_col - 3;
    msg_right = msg_col + active_msg_len + 3;
    if (msg_top < 0) msg_top = 0;
    if (msg_bottom >= LINES) msg_bottom = LINES - 1;
    if (msg_left < 0) msg_left = 0;
    if (msg_right >= COLS) msg_right = COLS - 1;
}

int in_message_rect(int y, int x) {
    if (!active_message) return 0;
    return (y >= msg_top && y <= msg_bottom && x >= msg_left && x <= msg_right);
}

void draw_message() {
    if (!active_message) return;
    // Blank rectangle with spaces (no color, no bold)
    attrset(A_NORMAL);
    for (int y = msg_top; y <= msg_bottom; y++) {
        for (int x = msg_left; x <= msg_right; x++) {
            mvaddch(y, x, ' ');
        }
    }
    // Draw message centered, plain (no color, no bold)
    attrset(A_NORMAL);
    // Handle long message truncation: if msg_len > COLS, mvaddnstr?
    // Use mvaddstr, ncurses will truncate at edge? But need to handle msg_col negative? Already clamped.
    // If message longer than COLS, start at 0 and truncate.
    if (active_msg_len > COLS) {
        mvaddnstr(msg_row, 0, active_message, COLS);
    } else {
        mvaddstr(msg_row, msg_col, active_message);
    }
    attrset(A_NORMAL);
}

// Init columns
void init_columns(int use_old_fewer) {
    (void)use_old_fewer;
    num_mcols = (COLS + 1) / 2;
    if (num_mcols < 1) num_mcols = 1;
    if (mcols) free(mcols);
    mcols = calloc(num_mcols, sizeof(MatrixCol));
    for (int i = 0; i < num_mcols; i++) {
        mcols[i].y = (rand() % (LINES + LINES/2)) - LINES/2 - 5;
        // len: random 5 to LINES*2/3?
        int maxlen = LINES * 2 / 3;
        if (maxlen < 5) maxlen = 5;
        mcols[i].len = 5 + (rand() % (maxlen > 5 ? maxlen - 5 : 5));
        if (mcols[i].len < 5) mcols[i].len = 5;
        mcols[i].space = 3 + (rand() % 10);
        mcols[i].speed = 1 + (rand() % 3);
        mcols[i].count = rand() % mcols[i].speed;
        mcols[i].active = 1;
        // For old/async with fewer heads: randomly make some columns inactive initially with longer space?
        if (opt_old || opt_async) {
            // 30% chance to start waiting with large negative y (inactive)?
            if (rand() % 100 < 30) {
                mcols[i].y = - (rand() % LINES) - mcols[i].len - mcols[i].space - 10;
            }
        }
    }
}

void reset_column(int i) {
    // Restart column with new random head above screen
    int maxlen = LINES * 2 / 3;
    if (maxlen < 5) maxlen = 5;
    mcols[i].len = 5 + (rand() % (maxlen > 5 ? maxlen - 5 : 5));
    mcols[i].space = 3 + (rand() % 10);
    // Start above screen: y = -space - rand?
    mcols[i].y = -(rand() % (LINES/2 + 5)) - 2;
    mcols[i].speed = 1 + (rand() % 3);
    mcols[i].count = 0;
}

