// UTF-8 helpers: encode wchar to utf8 string (caller provides buf[5])
int encode_utf8(int wc, char *buf) {
    if (wc < 0x80) {
        buf[0] = wc;
        buf[1] = '\0';
        return 1;
    } else if (wc < 0x800) {
        buf[0] = 0xC0 | (wc >> 6);
        buf[1] = 0x80 | (wc & 0x3F);
        buf[2] = '\0';
        return 2;
    } else {
        buf[0] = 0xE0 | (wc >> 12);
        buf[1] = 0x80 | ((wc >> 6) & 0x3F);
        buf[2] = 0x80 | (wc & 0x3F);
        buf[3] = '\0';
        return 3;
    }
}

