    int use_rainbow = opt_rainbow;
    int color_pair = 1;
    int fg = matrix_color;
    if (use_rainbow) {
        if (rainbow_c == -1) fg = rand_rainbow_color();
        else fg = rainbow_c;
        color_pair = rainbow_pair(fg);
    } else {
        if (is_head) {
            // Heads white, except for -c (no white) and -r (no white, but handled above)
            if (opt_japanese) {
                // -c: heads same as trail (green, no white)
                color_pair = 1;
                fg = matrix_color;
            } else {
                // Normal: white heads
                // For -C white, matrix white, heads white (same)
                color_pair = 2;
                fg = COLOR_WHITE;
            }
        } else {
            color_pair = 1;
            fg = matrix_color;
        }
    }

    int attr = A_NORMAL;
    // Bold logic
    if (opt_bold_mode == 2) {
        attr = A_BOLD;
    } else if (opt_bold_mode == 1) {
        if (is_head) attr = A_BOLD;
        else {
            // For -x with many white? Heads already bold, trail random bold? Keep same.
            if (rand() % 2 == 0) attr = A_BOLD;
            else attr = A_NORMAL;
        }
    } else if (opt_bold_mode == 3) {
        // Flag -n: heads bold, trail normal
        if (is_head) {
            // For -c with no white heads? In -c, is_head is still considered head? But -c has no white, heads same color. Should they be bold?
            // Original -c has no white, but what about bold for -c? We didn't test -c + -n. Assume heads bold still?
            // For -c, is_head true means head position, should be bold if mode 3.
            attr = A_BOLD;
        } else {
            attr = A_NORMAL;
        }
    } else { // 0 default, no bold
        attr = A_NORMAL;
    }

    // Special for -x: many white? Implement as: for -x, trail randomly white 25%?
    // We'll handle -x white randomization here: if opt_xwindow and !is_head and !use_rainbow, 25% chance to make white instead of matrix color?
    int is_white_extra = 0;
    if (opt_xwindow && !is_head && !use_rainbow && !opt_japanese) {
        if (rand() % 100 < 25) {
            is_white_extra = 1;
            color_pair = 2;
            // Bold for extra white? Same as heads? For -x default (no bold flag), heads are plain white (no bold)? Wait default -x: what bold? We didn't test -x bold. Assume same as default: no bold.
            // For extra white, use same bold as trail? For mode 0, normal; for mode 1, random? For mode 3, trail normal, but extra white? Should be normal? Hmm.
            // Simplify: extra white follows trail bold logic (not head).
            // Already set attr based on is_head false (trail). Keep it.
            // But for mode 3 (heads bold), extra white should be normal (since it's trail)? Keep as is.
        }
    }

    // Choose character
    char utf8buf[8];
    char *ch_str = NULL;
    int ch_ascii = ' ';
    int is_utf8 = 0;

    if (opt_lambda && !is_head && !is_white_extra) {
        // Lambda for green trail (not heads, not extra white)
        // Lambda is U+03BB, utf8 CE BB
        utf8buf[0] = (char)0xCE; utf8buf[1] = (char)0xBB; utf8buf[2] = '\0';
        ch_str = utf8buf;
        is_utf8 = 1;
        // Need to copy to local? We'll use mvaddstr directly, so need to handle attr.
    } else if (opt_japanese && !is_white_extra) {
        // For -c: matrix cols katakana (both head and trail, since no white distinction? But heads same color)
        // If lambda and japanese: lambda overrides katakana for trail (as observed -c -m gives lambda). Already handled above for trail lambda.
        // For heads in -c -m: heads should be? In -c -m, heads? -c has no white, heads same as trail? But -m says heads remain ASCII? For -c -m, heads? Hmm.
        // Simplify: if lambda and is_head and japanese: use katakana? Or ASCII? Original -c -m had only green lambda, no katakana, so heads also lambda? Actually -c -m had lambda only, no katakana. So for -c -m, both head and trail lambda? But our code makes heads ASCII (since lambda only for !is_head). That would give katakana heads, lambda trail, not matching.
        // For -c -m, should all be lambda? Let's make: if japanese and lambda, all lambda (both head and trail) for matrix cols.
        if (opt_lambda) {
            utf8buf[0] = (char)0xCE; utf8buf[1] = (char)0xBB; utf8buf[2] = '\0';
            ch_str = utf8buf;
            is_utf8 = 1;
        } else {
            int wc = rand_katakana_wc();
            encode_utf8(wc, utf8buf);
            // Need to keep buf alive for mvaddstr; use static? We'll just mvaddstr immediately.
            ch_str = utf8buf;
            is_utf8 = 1;
        }
