        ch_str = utf8buf;
        is_utf8 = 1;
    } else {
        // Default / old charset
        if (opt_lambda && !is_head && !is_white_extra) {
            // Already handled above, but double-check
            utf8buf[0] = (char)0xCE; utf8buf[1] = (char)0xBB; utf8buf[2] = '\0';
            ch_str = utf8buf;
            is_utf8 = 1;
        } else {
            if (opt_old) ch_ascii = rand_old_char();
            else ch_ascii = rand_default_char();
            is_utf8 = 0;
        }
    }

    // For -m with rainbow? Rainbow lambda: each lambda random color (already handled via rainbow_c). Good.

    // Apply color/bold and draw
    int pair_to_use = color_pair;
    // For black on black, ncurses will optimize to no color (as desired). Good.
    // For gaps? This is matrix col, always colored (even spaces? But here ch is never space, always visible char. Spaces for clearing handled separately.)

    if (has_colors()) {
        attrset(attr | COLOR_PAIR(pair_to_use));
    } else {
        attrset(attr);
    }
    if (is_utf8) {
        // ch_str points to utf8buf which is local; need to ensure null-terminated and valid
        // For japanese/x/lambda, utf8buf is set. But for lambda case above, utf8buf is also local. Need to handle scope: utf8buf is local to this function, valid here.
        // However for lambda/japanese/x branches, we set ch_str to utf8buf, which is still valid.
        mvaddstr(y, x, ch_str);
    } else {
        mvaddch(y, x, ch_ascii);
    }
    attrset(A_NORMAL);
}

void clear_matrix_char(int y, int x) {
    if (y < 0 || y >= LINES || x < 0 || x >= COLS) return;
