    // Actually rainbow total 800 suggests 160 blank matrix cells are plain (not colored). Which ones? Possibly inactive columns' spaces are plain? Hard.
    // Simplify: for rainbow, clear with plain space.

    int attr = A_NORMAL;
    if (opt_bold_mode == 2) attr = A_BOLD;
    else if (opt_bold_mode == 1) {
        if (rand() % 2 == 0) attr = A_BOLD;
    } else if (opt_bold_mode == 3) {
        attr = A_NORMAL; // trail clear is trail, not head, so normal
    } else {
        attr = A_NORMAL;
    }

    if (opt_rainbow) {
        // Plain space for rainbow blanks? Or random? Use plain.
        attrset(attr);
